"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[372],{3498:e=>{e.exports=JSON.parse('{"functions":[{"name":"get","desc":"Returns the current value without yielding. On the server, errors if the player\'s saved data hasn\'t loaded yet.\\n\\nOn the client, errors if the value hasn\'t arrived yet. Call [Sencha.waitForReplicators] while loading, or use\\n[SavedReplicator:getAsync] or [SavedReplicator:observe] in code that may run earlier.\\n\\nOn the client, this includes pending predictions. [SavedReplicator:getConfirmed] returns the server\'s value\\nwithout them.","params":[{"name":"player","desc":"required on the server, left out on the client","lua_type":"Player?"}],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","source":{"line":120,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"getAsync","desc":"Returns the current value, yielding until it\'s available. On the server, waits for the player\'s saved data to load.\\n\\nOn the client, this includes pending predictions. [SavedReplicator:getConfirmed] returns the server\'s value\\nwithout them.","params":[{"name":"player","desc":"required on the server, left out on the client","lua_type":"Player?"}],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","yields":true,"source":{"line":150,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"onChanged","desc":"Calls `callback` when the value changes, not for the initial value. On the server this fires for any player whose\\nvalue changes; on the client `player` is always the local player.\\n\\nOn the server, the change is sent to clients before `callback` runs, so anything it changes in response reaches\\nclients after the change that caused it.\\n\\nOn the client, this also fires when a prediction is made, and again if it\'s rolled back. Use\\n[SavedReplicator:onConfirmedChanged] to only hear about the server\'s changes.","params":[{"name":"callback","desc":"","lua_type":"(player: Player, newValue: T, oldValue: T) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","source":{"line":177,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"observe","desc":"Calls `callback` with the current value right away if it has arrived (otherwise when it arrives), then on\\nevery change. `oldValue` is the value before the change, or `nil` for the first call.\\n\\n```lua\\nResearchNetwork.researchReplicator:observe(function(research, oldResearch)\\n\\tprint(`researched {#research} items, up from {if oldResearch then #oldResearch else 0}`)\\nend)\\n```\\n\\nThis includes predictions: it fires when a prediction is made, and again if it\'s rolled back.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T?) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":209,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"onUpdateReceived","desc":"Calls `callback` for each patch received, after the value is updated. Only replicators with an incremental\\nconfig receive patches; calling this on one without errors.\\n\\nThe first value is a whole value, so it doesn\'t fire this; use [SavedReplicator:onChanged] to see every change.\\n\\nPatches always come from the server: predictions don\'t fire this, and `newValue` and `oldValue` are the\\nserver\'s values.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T, patch: P) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":230,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"getObservable","desc":"Returns an [ObservableValue](https://jdevon.github.io/observable-value/) that follows the replicated value,\\nfor code that works with ObservableValues, like the\\n[ReactObservableValue](https://github.com/JDevon/react-observable-value) hooks. Calling this again returns the same\\none. Setting it doesn\'t change the replicated value. Errors if the value hasn\'t arrived yet.\\n\\n```lua\\nlocal research = ReactObservableValue.useObservableValue(ResearchNetwork.researchReplicator:getObservable())\\n```\\n\\nThe observable includes pending predictions, like [SavedReplicator:get].","params":[],"returns":[{"desc":"","lua_type":"ObservableValue<T>"}],"function_type":"method","realm":["Client"],"source":{"line":256,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"getConfirmed","desc":"Returns the value the server sent, without any pending predictions. [SavedReplicator:get] returns the predicted\\nvalue while a prediction is pending; use this when code must only act on what the server has confirmed. Errors if\\nthe value hasn\'t arrived yet.","params":[],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","realm":["Client"],"source":{"line":272,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"onConfirmedChanged","desc":"Calls `callback` when the server\'s value changes, not for predictions or the initial value. `player` is always the\\nlocal player.\\n\\n[SavedReplicator:onChanged] also fires for predictions, and again if a wrong prediction is rolled back. Use this\\ninstead for effects that should only change for confirmed values:\\n\\n```lua\\nResearchNetwork.researchReplicator:onConfirmedChanged(function(_player, research, oldResearch)\\n\\tprint(`the server confirmed {#research} researched items`)\\nend)\\n```","params":[{"name":"callback","desc":"","lua_type":"(player: Player, newValue: T, oldValue: T) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":297,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"prediction","desc":"Builds a prediction for this replicator. The returned prediction can be used with a predicted remote call such as\\n`invokeServerPredicted` or `fireServerPredicted`. While the call is pending, [SavedReplicator:get],\\n[SavedReplicator:observe] and [SavedReplicator:onChanged] show the value with the prediction applied; it\'s removed\\nwhen the server confirms the call.\\n\\n`predict` is either a function that returns the predicted value, or a patch on a replicator with an incremental\\nconfig. A patch is applied with the config\'s `apply`, the same way the server\'s patches are.\\n\\n```lua\\nResearchNetwork.researchRemote:invokeServerPredicted({\\n\\tResearchNetwork.researchReplicator:prediction(function(research)\\n\\t\\tlocal newResearch = table.clone(research)\\n\\t\\ttable.insert(newResearch, \\"drills\\")\\n\\t\\treturn newResearch\\n\\tend),\\n}, \\"drills\\")\\n```","params":[{"name":"predict","desc":"","lua_type":"((value: T) -> T) | P"}],"returns":[{"desc":"","lua_type":"Prediction"}],"function_type":"method","realm":["Client"],"source":{"line":333,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}},{"name":"isLoaded","desc":"Returns whether the value has arrived from the server.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","realm":["Client"],"source":{"line":350,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}}],"properties":[],"types":[],"name":"SavedReplicator","desc":"A read-only view of part of a player\'s saved data, created with [SavedSource:replicator]. Its value is sent\\nonly to the player it belongs to.\\n\\nTo change it, update the saved data; the change replicates when the store calls [SavedSource:replicateChanges].\\nThis keeps one write path, so an update to several fields at once stays atomic.","source":{"line":23,"path":"src/Replication/Kinds/SavedReplicator/init.luau"}}')}}]);